payload.template:
module mux4 #(parameter int W = 8) (
  input  logic [W-1:0] d0, d1, d2, d3,
  input  logic [1:0]   sel,
  output logic [W-1:0] y
);

  // your code here: select one of the four inputs according to sel.
  // Combinational — every path must assign y, or you have built a
  // latch rather than a multiplexer.

endmodule

payload.testbench:
`timescale 1ns/1ps
// The sample testbench. Run uses this one; Submit uses a different
// one that tries cases this does not.
module tb;
  localparam int W = 8;
  logic [W-1:0] d0, d1, d2, d3, y;
  logic [1:0]   sel;

  mux4 #(.W(W)) dut (.d0(d0), .d1(d1), .d2(d2), .d3(d3), .sel(sel), .y(y));

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    d0 = 8'h11; d1 = 8'h22; d2 = 8'h33; d3 = 8'h44;

    sel = 2'b00; #1;
    $display("CHECK sel0 %h %h AT %0d", 8'h11, y, $time);
    sel = 2'b01; #1;
    $display("CHECK sel1 %h %h AT %0d", 8'h22, y, $time);
    sel = 2'b10; #1;
    $display("CHECK sel2 %h %h AT %0d", 8'h33, y, $time);
    sel = 2'b11; #1;
    $display("CHECK sel3 %h %h AT %0d", 8'h44, y, $time);

    #2;
    $display("DONE 4");
    $finish;
  end
endmodule
